#!/usr/bin/env python3
"""Lossless compression for a mixed structured text corpus; stdlib only."""
import sys
import bz2
import zlib

META_PREFIX = b'e18a line '
ALPHABET = b'0123456789abcdefghijklmnopqrstuvwxyz'


def encode(data):
    lines = data.splitlines(keepends=True)
    tags = bytearray((len(lines) + 3) // 4)
    payload = bytearray()
    for i, line in enumerate(lines):
        if not line.endswith(b'\n'):
            return b'B' + bz2.compress(data, compresslevel=9)
        s = line[:-1]
        if len(s) == 96 and all(x in b'0123456789abcdef' for x in s):
            typ = 0
            payload.extend(bytes.fromhex(s.decode('ascii')))
        elif len(s) == 64 and all(x in ALPHABET for x in s):
            typ = 1
            payload.extend(int(s, 36).to_bytes(42, 'big'))
        elif s.startswith(META_PREFIX):
            parts = s.split()
            if (len(parts) != 10 or parts[0] != b'e18a' or parts[1] != b'line'
                    or parts[3] != b'ratio' or parts[5:8] != [b'select', b'pick', b'win']
                    or parts[8] != b'seed'):
                return b'B' + bz2.compress(data, compresslevel=9)
            try:
                line_no, ratio, seed = int(parts[2]), parts[4], int(parts[9])
                if len(ratio) != 8 or ratio[1:2] != b'.' or not ratio[:1].isdigit() or not ratio[2:].isdigit():
                    raise ValueError
                r = int(ratio[:1]) * 1000000 + int(ratio[2:])
                if not (0 <= line_no < 2**24 and 0 <= r < 2**24 and 0 <= seed < 2**32):
                    raise ValueError
            except ValueError:
                return b'B' + bz2.compress(data, compresslevel=9)
            typ = 2
            payload.extend(line_no.to_bytes(3, 'big'))
            payload.extend(r.to_bytes(3, 'big'))
            payload.extend(seed.to_bytes(4, 'big'))
        else:
            return b'B' + bz2.compress(data, compresslevel=9)
        tags[i // 4] |= typ << (2 * (i % 4))
    return b'S' + len(lines).to_bytes(4, 'big') + zlib.compress(tags, 9) + b'\0' + payload


def decode(data):
    if data[:1] == b'B':
        return bz2.decompress(data[1:])
    if data[:1] != b'S':
        raise ValueError('invalid file')
    n = int.from_bytes(data[1:5], 'big')
    # The tag stream has fixed uncompressed size, so a decompressor identifies its end.
    obj = zlib.decompressobj()
    tags = obj.decompress(data[5:], (n + 3) // 4)
    # Finish the compressed stream if necessary (typically the zlib checksum).
    remainder = obj.unconsumed_tail
    if not obj.eof:
        obj.decompress(remainder)
    payload = memoryview(obj.unused_data if obj.eof else b'')
    if not payload:
        # Safely locate the zlib stream boundary using a separate full decode.
        obj = zlib.decompressobj()
        tags = obj.decompress(data[5:])
        payload = memoryview(obj.unused_data)
    if len(tags) != (n + 3) // 4:
        raise ValueError('invalid tags')
    result = bytearray()
    pos = 0
    for i in range(n):
        typ = (tags[i // 4] >> (2 * (i % 4))) & 3
        if typ == 0:
            result.extend(payload[pos:pos + 48].tobytes().hex().encode())
            pos += 48
        elif typ == 1:
            num = int.from_bytes(payload[pos:pos + 42], 'big')
            chars = bytearray(64)
            for j in range(63, -1, -1):
                num, rem = divmod(num, 36)
                chars[j] = ALPHABET[rem]
            result.extend(chars)
            pos += 42
        elif typ == 2:
            line_no = int.from_bytes(payload[pos:pos + 3], 'big')
            r = int.from_bytes(payload[pos + 3:pos + 6], 'big')
            seed = int.from_bytes(payload[pos + 6:pos + 10], 'big')
            result.extend(b'e18a line %d ratio %d.%06d select pick win seed %d' % (line_no, r // 1000000, r % 1000000, seed))
            pos += 10
        else:
            raise ValueError('invalid tag')
        result.append(10)
    if pos != len(payload):
        raise ValueError('invalid payload size')
    return bytes(result)


def main():
    args = sys.argv[1:]
    if len(args) == 3 and args[0] == '--decompress':
        out = decode(open(args[1], 'rb').read())
        open(args[2], 'wb').write(out)
    elif len(args) == 2:
        open(args[1], 'wb').write(encode(open(args[0], 'rb').read()))
    else:
        raise SystemExit('usage: compress.py [--decompress] input output')


if __name__ == '__main__':
    main()

