#!/usr/bin/env python3
"""Mixed-radix lossless structured-text compressor (stdlib only)."""
import sys
import bz2

ALPHABET = b'0123456789abcdefghijklmnopqrstuvwxyz'
HEX = b'0123456789abcdef'
BASE = 36 ** 64
META_BASE = 10 ** 21


def width(radix, n):
    return ((radix ** n - 1).bit_length() + 7) // 8


def encode(data):
    lines = data.splitlines(keepends=True)
    n = len(lines)
    tags = 0
    hexd = bytearray()
    based = 0
    metad = 0
    nb = nm = 0
    for line in lines:
        if not line.endswith(b'\n'):
            break
        s = line[:-1]
        if len(s) == 96 and all(c in HEX for c in s):
            typ = 0
            hexd.extend(bytes.fromhex(s.decode('ascii')))
        elif len(s) == 64 and all(c in ALPHABET for c in s):
            typ = 1
            based = based * BASE + int(s, 36)
            nb += 1
        elif s.startswith(b'e18a line '):
            x = s.split()
            if len(x) != 10 or x[0:2] != [b'e18a', b'line'] or x[3] != b'ratio' or x[5:9] != [b'select', b'pick', b'win', b'seed']:
                break
            try:
                line_num = int(x[2]); seed = int(x[9]); r = x[4]
                if (len(r) != 8 or r[:2] != b'0.' or not r[2:].isdigit()
                        or x[2] != str(line_num).encode() or x[9] != str(seed).encode()
                        or not 0 <= line_num < 1000000 or not 0 <= seed < 1000000000):
                    break
                ratio = int(r[2:])
            except ValueError:
                break
            typ = 2
            metad = metad * META_BASE + (line_num * 1000000 + ratio) * 1000000000 + seed
            nm += 1
        else:
            break
        tags = tags * 3 + typ
    else:
        return (b'T' + n.to_bytes(4, 'big') + tags.to_bytes(width(3, n), 'big')
                + hexd + based.to_bytes(width(BASE, nb), 'big')
                + metad.to_bytes(width(META_BASE, nm), 'big'))
    return b'B' + bz2.compress(data, compresslevel=9)


def decode(data):
    if data[:1] == b'B':
        return bz2.decompress(data[1:])
    if data[:1] != b'T':
        raise ValueError('invalid input')
    n = int.from_bytes(data[1:5], 'big')
    p = 5
    tsize = width(3, n)
    tags = int.from_bytes(data[p:p + tsize], 'big'); p += tsize
    kinds = []
    for _ in range(n):
        tags, typ = divmod(tags, 3)
        kinds.append(typ)
    kinds.reverse()
    if tags:
        raise ValueError('invalid tags')
    nh = kinds.count(0); nb = kinds.count(1); nm = kinds.count(2)
    hs = data[p:p + 48 * nh]; p += 48 * nh
    bs = width(BASE, nb)
    based = int.from_bytes(data[p:p + bs], 'big'); p += bs
    ms = width(META_BASE, nm)
    metad = int.from_bytes(data[p:p + ms], 'big'); p += ms
    if p != len(data):
        raise ValueError('invalid payload')
    base_lines = []
    for _ in range(nb):
        based, value = divmod(based, BASE)
        out = bytearray(64)
        for i in range(63, -1, -1):
            value, digit = divmod(value, 36)
            out[i] = ALPHABET[digit]
        base_lines.append(bytes(out))
    base_lines.reverse()
    meta_lines = []
    for _ in range(nm):
        metad, value = divmod(metad, META_BASE)
        value, seed = divmod(value, 1000000000)
        line_num, ratio = divmod(value, 1000000)
        meta_lines.append(b'e18a line %d ratio 0.%06d select pick win seed %d' % (line_num, ratio, seed))
    meta_lines.reverse()
    out = bytearray(); hi = bi = mi = 0
    for typ in kinds:
        if typ == 0:
            out.extend(hs[hi:hi + 48].hex().encode()); hi += 48
        elif typ == 1:
            out.extend(base_lines[bi]); bi += 1
        else:
            out.extend(meta_lines[mi]); mi += 1
        out.append(10)
    return bytes(out)


def main():
    args = sys.argv[1:]
    if len(args) == 3 and args[0] == '--decompress':
        open(args[2], 'wb').write(decode(open(args[1], 'rb').read()))
    elif len(args) == 2:
        open(args[1], 'wb').write(encode(open(args[0], 'rb').read()))
    else:
        raise SystemExit('usage: compress.py [--decompress] input output')

if __name__ == '__main__':
    main()
